class Solution:
    def trappedWater(self, walls: List[int]) -> int:
        n = len(walls)
        total = 0
        for i in range(n):
            left = max(walls[:i + 1])
            right = max(walls[i:])
            total += min(left, right) - walls[i]
        return total

