class Solution {
    public long trappedWater(int[] walls) {
        int n = walls.length;
        long total = 0;
        for (int i = 0; i < n; i++) {
            int left = 0, right = 0;
            for (int k = 0; k <= i; k++) left = Math.max(left, walls[k]);
            for (int k = i; k < n; k++) right = Math.max(right, walls[k]);
            total += Math.min(left, right) - walls[i];
        }
        return total;
    }
}

