long long trappedWater(int* walls, int wallsSize) {
    int n = wallsSize;
    long long total = 0;
    for (int i = 0; i < n; i++) {
        int left = 0, right = 0;
        for (int k = 0; k <= i; k++) if (walls[k] > left) left = walls[k];
        for (int k = i; k < n; k++) if (walls[k] > right) right = walls[k];
        total += (left < right ? left : right) - walls[i];
    }
    return total;
}

