class Solution:
    def trappedWater(self, walls: List[int]) -> int:
        n = len(walls)
        left_max = [0] * n
        left_max[0] = walls[0]
        for i in range(1, n):
            left_max[i] = max(left_max[i - 1], walls[i])
        right_max = [0] * n
        right_max[-1] = walls[-1]
        for i in range(n - 2, -1, -1):
            right_max[i] = max(right_max[i + 1], walls[i])
        return sum(min(left_max[i], right_max[i]) - walls[i] for i in range(n))

