class Solution {
    public long trappedWater(int[] walls) {
        int n = walls.length;
        int[] leftMax = new int[n], rightMax = new int[n];
        leftMax[0] = walls[0];
        for (int i = 1; i < n; i++) leftMax[i] = Math.max(leftMax[i - 1], walls[i]);
        rightMax[n - 1] = walls[n - 1];
        for (int i = n - 2; i >= 0; i--) rightMax[i] = Math.max(rightMax[i + 1], walls[i]);
        long total = 0;
        for (int i = 0; i < n; i++) total += Math.min(leftMax[i], rightMax[i]) - walls[i];
        return total;
    }
}

