long long trappedWater(int* walls, int wallsSize) {
    int n = wallsSize;
    int* leftMax = malloc(n * sizeof(int));
    int* rightMax = malloc(n * sizeof(int));
    leftMax[0] = walls[0];
    for (int i = 1; i < n; i++) leftMax[i] = walls[i] > leftMax[i - 1] ? walls[i] : leftMax[i - 1];
    rightMax[n - 1] = walls[n - 1];
    for (int i = n - 2; i >= 0; i--) rightMax[i] = walls[i] > rightMax[i + 1] ? walls[i] : rightMax[i + 1];
    long long total = 0;
    for (int i = 0; i < n; i++) total += (leftMax[i] < rightMax[i] ? leftMax[i] : rightMax[i]) - walls[i];
    free(leftMax);
    free(rightMax);
    return total;
}

